// A NriDonutSceneHandle.
@final
export class NriDonutScene {
    constructor(public readonly handle: NriDonutSceneHandle) {
    }

    // A dynamic mesh (Donut_CreateDynamicMesh + Donut_AttachDynamicMesh) added to the scene: one geometry of
    // maxVertices float3 positions followed by maxVertices float2 texture coordinates in bindless buffer
    // vertexBufferIndex and maxIndices 32-bit indices in bindless buffer indexBufferIndex, its material
    // alpha-blended (Donut's default otherwise), an instance (identity transform) after the scene's. Create
    // the scene's buffers 2 to 4 after it. The instance's index.
    // (Nri_AddDonutSceneDynamicMesh)
    addDynamicMesh(maxVertices: int, maxIndices: int, vertexBufferIndex: int, indexBufferIndex: int): int {
        return Nri_AddDonutSceneDynamicMesh(this.handle, maxVertices, maxIndices, vertexBufferIndex, indexBufferIndex);
    }

    // (Nri_DestroyDonutScene)
    destroy() {
        Nri_DestroyDonutScene(this.handle);
    }

    // The scene's bounds (its scene graph root's global bounding box): 6 floats into dst, min x, y, z, max
    // x, y, z.
    // (Nri_GetDonutSceneBounds)
    getBounds(dst: Ref<f32>) {
        Nri_GetDonutSceneBounds(this.handle, dst);
    }

    // The mesh instances (each's InstanceData index its number), their geometries, each geometry's
    // index count: a draw each.
    // The meshes' geometries (the GeometryData buffer's entries), in global geometry order.
    // (Nri_GetDonutSceneGeometryCount)
    getGeometryCount(): int {
        return Nri_GetDonutSceneGeometryCount(this.handle);
    }

    // A geometry's first index in the index buffer, its first vertex in the streams (its indices count
    // from it) and its material.
    // (Nri_GetDonutSceneGeometryFirstIndex)
    getGeometryFirstIndex(instance: int, geometry: int): int {
        return Nri_GetDonutSceneGeometryFirstIndex(this.handle, instance, geometry);
    }

    // (Nri_GetDonutSceneGeometryFirstVertex)
    getGeometryFirstVertex(instance: int, geometry: int): int {
        return Nri_GetDonutSceneGeometryFirstVertex(this.handle, instance, geometry);
    }

    // (Nri_GetDonutSceneGeometryIndexCount)
    getGeometryIndexCount(instance: int, geometry: int): int {
        return Nri_GetDonutSceneGeometryIndexCount(this.handle, instance, geometry);
    }

    // (Nri_GetDonutSceneGeometryMaterial)
    getGeometryMaterial(instance: int, geometry: int): int {
        return Nri_GetDonutSceneGeometryMaterial(this.handle, instance, geometry);
    }

    // The BLAS Nri_BuildDonutSceneAccelStructs built for an instance's mesh, for TLASes the example builds
    // itself (Nri_TopLevelASAddInstance); null if it built none for it.
    // (Nri_GetDonutSceneInstanceBlas)
    getInstanceBlas(accelStructs: NriDonutSceneAccelStructs, instance: int): NriAccelerationStructure | null {
        const result = Nri_GetDonutSceneInstanceBlas(this.handle, accelStructs.handle, instance);
        return result ? new NriAccelerationStructure(result) : null;
    }

    // (Nri_GetDonutSceneInstanceCount)
    getInstanceCount(): int {
        return Nri_GetDonutSceneInstanceCount(this.handle);
    }

    // (Nri_GetDonutSceneInstanceGeometryCount)
    getInstanceGeometryCount(instance: int): int {
        return Nri_GetDonutSceneInstanceGeometryCount(this.handle, instance);
    }

    // An instance's transform, as the TLAS takes it (12 floats into dst, Ref of an f32 array element).
    // (Nri_GetDonutSceneInstanceTransform)
    getInstanceTransform(instance: int, dst: Ref<f32>) {
        Nri_GetDonutSceneInstanceTransform(this.handle, instance, dst);
    }

    // The materials: their count, each's texture in a slot (0 base or diffuse, 1 metal-rough or
    // specular, 2 normal, 3 emissive, 4 occlusion, 5 transmission, 6 opacity: the passes' t0 to t6; -1
    // for none), its domain (0 opaque, 1 alpha-tested, 2 alpha-blended, 3 to 5 transmissive) and whether
    // it's double-sided (drawn without culling).
    // (Nri_GetDonutSceneMaterialCount)
    getMaterialCount(): int {
        return Nri_GetDonutSceneMaterialCount(this.handle);
    }

    // (Nri_GetDonutSceneMaterialDomain)
    getMaterialDomain(material: int): int {
        return Nri_GetDonutSceneMaterialDomain(this.handle, material);
    }

    // (Nri_GetDonutSceneMaterialDoubleSided)
    getMaterialDoubleSided(material: int): int {
        return Nri_GetDonutSceneMaterialDoubleSided(this.handle, material);
    }

    // (Nri_GetDonutSceneMaterialTexture)
    getMaterialTexture(material: int, slot: int): int {
        return Nri_GetDonutSceneMaterialTexture(this.handle, material, slot);
    }

    // The byte offset of a vertex stream in the vertex buffer: 0 positions (float3), 1 texture
    // coordinates (float2), 2 normals, 3 tangents (snorm8 each).
    // (Nri_GetDonutSceneStreamOffset)
    getStreamOffset(stream: int): int {
        return Nri_GetDonutSceneStreamOffset(this.handle, stream);
    }

    // The textures the materials number (their files relative to the executable's folder; 1 if sRGB).
    // (Nri_GetDonutSceneTextureCount)
    getTextureCount(): int {
        return Nri_GetDonutSceneTextureCount(this.handle);
    }

    // (Nri_GetDonutSceneTexturePath)
    getTexturePath(texture: int): string {
        return Nri_GetDonutSceneTexturePath(this.handle, texture);
    }

    // (Nri_GetDonutSceneTextureSrgb)
    getTextureSrgb(texture: int): int {
        return Nri_GetDonutSceneTextureSrgb(this.handle, texture);
    }

    // A glTF scene as Donut's engine loads it (core/nri/nri_donut_scene.cpp): the buffers Donut's scene
    // shaders read, the instances' transforms composed with Donut's math. Null (after printing why) on
    // failure. Path relative to the executable's folder.
    // (Nri_LoadDonutScene)
    static load(path: string): NriDonutScene | null {
        const result = Nri_LoadDonutScene(path);
        return result ? new NriDonutScene(result) : null;
    }

    // A material's base or diffuse texture (its bindless texture index; -1: none), as
    // Donut_SetDynamicMeshTexture sets the dynamic mesh's. Create the scene's buffer 4 after it.
    // (Nri_SetDonutSceneMaterialBaseTexture)
    setMaterialBaseTexture(material: int, textureIndex: int) {
        Nri_SetDonutSceneMaterialBaseTexture(this.handle, material, textureIndex);
    }
}

