// A NriDrawListHandle.
@final
export class NriDrawList {
    constructor(public readonly handle: NriDrawListHandle) {
    }

    // Draw passes recorded on worker threads: a draw list is a pass's draws (pipelines by slot, sets,
    // root constants, indexed draws), made once; a draw pass records it into a command buffer of its
    // own, set up first (attachments cleared, viewport, layout, sets, root descriptors, index buffer), on
    // the calling thread (Nri_RecordDrawPass) or on a worker thread (Nri_RecordDrawPassAsync, then
    // Nri_WaitDrawPass): C++ doing what TypeScript can't do on threads its garbage collector doesn't
    // know about.
    // (Nri_CreateDrawList)
    static create(): NriDrawList {
        return new NriDrawList(Nri_CreateDrawList());
    }

    // A pass recording the list (which must outlive it) into width x height color (null: none, a depth-only
    // pass) and depth attachments, with the layout (graphics) and the pool's sets. Destroying it waits for
    // its worker.
    // (Nri_CreateDrawPass)
    createDrawPass(colorAttachment: NriDescriptor | null, depthAttachment: NriDescriptor, width: int, height: int, layout: NriPipelineLayout, descriptorPool: NriDescriptorPool): NriDrawPass {
        return new NriDrawPass(Nri_CreateDrawPass(this.handle, colorAttachment ? colorAttachment.handle : null, depthAttachment.handle, width, height, layout.handle, descriptorPool.handle));
    }

    // (Nri_DestroyDrawList)
    destroy() {
        Nri_DestroyDrawList(this.handle);
    }

    // (Nri_DrawListDrawIndexed)
    drawIndexed(indexNum: int, instanceNum: int, baseIndex: int, baseVertex: int, baseInstance: int) {
        Nri_DrawListDrawIndexed(this.handle, indexNum, instanceNum, baseIndex, baseVertex, baseInstance);
    }

    // (Nri_DrawListSetDescriptorSet)
    setDescriptorSet(setIndex: int, descriptorSet: NriDescriptorSet) {
        Nri_DrawListSetDescriptorSet(this.handle, setIndex, descriptorSet.handle);
    }

    // The draws from here on use the pass's pipeline in slot (Nri_DrawPassSetPipeline).
    // (Nri_DrawListSetPipeline)
    setPipeline(slot: int) {
        Nri_DrawListSetPipeline(this.handle, slot);
    }

    // size bytes of root constants (copied from data) at root constant index.
    // (Nri_DrawListSetRootConstants)
    setRootConstants(rootConstantIndex: int, data: Ref<f32>, size: int) {
        Nri_DrawListSetRootConstants(this.handle, rootConstantIndex, data, size);
    }
}

// A NriDrawPassHandle.
@final
export class NriDrawPass {
    constructor(public readonly handle: NriDrawPassHandle) {
    }

    // (Nri_DestroyDrawPass)
    destroy() {
        Nri_DestroyDrawPass(this.handle);
    }

    // Records the pass into the command buffer (beginning and ending it), on this thread.
    // (Nri_RecordDrawPass)
    record(commandBuffer: NriCommandBuffer) {
        Nri_RecordDrawPass(this.handle, commandBuffer.handle);
    }

    // As Nri_RecordDrawPass, on a worker thread; Nri_WaitDrawPass before submitting the command buffer or
    // changing the pass. Each pass recording at once needs its own command buffer and allocator.
    // (Nri_RecordDrawPassAsync)
    recordAsync(commandBuffer: NriCommandBuffer) {
        Nri_RecordDrawPassAsync(this.handle, commandBuffer.handle);
    }

    // The attachments' clear values (0 unless this says otherwise).
    // (Nri_DrawPassSetClear)
    setClear(r: float, g: float, b: float, a: float, depth: float) {
        Nri_DrawPassSetClear(this.handle, r, g, b, a, depth);
    }

    // Whether the attachments are cleared when the pass begins (1, the default) or kept (0).
    // (Nri_DrawPassSetClearEnabled)
    setClearEnabled(enabled: int) {
        Nri_DrawPassSetClearEnabled(this.handle, enabled);
    }

    // A set bound before the draws (or replacing the one at setIndex).
    // (Nri_DrawPassSetDescriptorSet)
    setDescriptorSet(setIndex: int, descriptorSet: NriDescriptorSet) {
        Nri_DrawPassSetDescriptorSet(this.handle, setIndex, descriptorSet.handle);
    }

    // The 32-bit index buffer the indexed draws read.
    // (Nri_DrawPassSetIndexBuffer)
    setIndexBuffer(buffer: NriBuffer) {
        Nri_DrawPassSetIndexBuffer(this.handle, buffer.handle);
    }

    // The pipeline the list's slot means (changeable between recordings).
    // (Nri_DrawPassSetPipeline)
    setPipeline(slot: int, pipeline: NriPipeline) {
        Nri_DrawPassSetPipeline(this.handle, slot, pipeline.handle);
    }

    // A root descriptor (a view) bound before the draws.
    // (Nri_DrawPassSetRootDescriptor)
    setRootDescriptor(rootDescriptorIndex: int, descriptor: NriDescriptor) {
        Nri_DrawPassSetRootDescriptor(this.handle, rootDescriptorIndex, descriptor.handle);
    }

    // The vertex buffer the draws read (stream 0), its vertices stride bytes apart.
    // (Nri_DrawPassSetVertexBuffer)
    setVertexBuffer(buffer: NriBuffer, stride: int) {
        Nri_DrawPassSetVertexBuffer(this.handle, buffer.handle, stride);
    }

    // (Nri_WaitDrawPass)
    wait() {
        Nri_WaitDrawPass(this.handle);
    }
}

