// A NriPipelineDescHandle.
@final
export class NriPipelineDesc {
    constructor(public readonly handle: NriPipelineDescHandle) {
    }

    // Another color attachment after the first (Nri_PipelineDescSetColor's): its format and the channels
    // written (NriColorWrite bits).
    // (Nri_PipelineDescAddColor)
    addColor(format: NriFormat, writeMask: int) {
        Nri_PipelineDescAddColor(this.handle, format, writeMask);
    }

    // Adds a shader read from path (as Nri_CreateGraphicsPipeline's); 0 if it can't be read.
    // (Nri_PipelineDescAddShader)
    addShader(stage: NriShaderStage, path: string, entry: string): int {
        return Nri_PipelineDescAddShader(this.handle, stage, path, entry);
    }

    // As Nri_PipelineDescAddShader, of a ShaderMake permutation blob (a .cfg line with -D), the
    // permutation whose defines are permutation ("NAME=VALUE").
    // (Nri_PipelineDescAddShaderPermutation)
    addShaderPermutation(stage: NriShaderStage, path: string, entry: string, permutation: string): int {
        return Nri_PipelineDescAddShaderPermutation(this.handle, stage, path, entry, permutation);
    }

    // An attribute of stream 0's vertices: semantic (index 0) on D3D, the next location on Vulkan (as
    // DXC numbers the vertex shader's inputs), format at offset bytes in the vertex.
    // (Nri_PipelineDescAddVertexAttribute)
    addVertexAttribute(semantic: string, format: NriFormat, offset: int) {
        Nri_PipelineDescAddVertexAttribute(this.handle, semantic, format, offset);
    }

    // As Nri_PipelineDescAddVertexAttribute, of stream's vertices (the vertex buffer bound to slot stream).
    // (Nri_PipelineDescAddVertexAttributeFromStream)
    addVertexAttributeFromStream(semantic: string, format: NriFormat, offset: int, stream: int) {
        Nri_PipelineDescAddVertexAttributeFromStream(this.handle, semantic, format, offset, stream);
    }

    // Pipeline descs: a graphics pipeline's shaders and states, set one by one. A new desc draws
    // triangles, not culled, without vertex input, color attachment or depth.
    // (Nri_CreatePipelineDesc)
    static create(): NriPipelineDesc {
        return new NriPipelineDesc(Nri_CreatePipelineDesc());
    }

    // (Nri_DestroyPipelineDesc)
    destroy() {
        Nri_DestroyPipelineDesc(this.handle);
    }

    // Additive blending into the color attachment, as Donut's BlendMode.Additive: color one + one, alpha
    // srcAlpha + dstAlpha.
    // (Nri_PipelineDescSetAdditiveBlend)
    setAdditiveBlend() {
        Nri_PipelineDescSetAdditiveBlend(this.handle);
    }

    // Blending into the first color attachment: color srcColor * source colorOp dstColor * destination,
    // alpha likewise.
    // (Nri_PipelineDescSetBlend)
    setBlend(srcColor: NriBlendFactor, dstColor: NriBlendFactor, colorOp: NriBlendOp, srcAlpha: NriBlendFactor, dstAlpha: NriBlendFactor, alphaOp: NriBlendOp) {
        Nri_PipelineDescSetBlend(this.handle, srcColor, dstColor, colorOp, srcAlpha, dstAlpha, alphaOp);
    }

    // The color attachment's format and the channels written (NriColorWrite bits).
    // (Nri_PipelineDescSetColor)
    setColor(format: NriFormat, writeMask: int) {
        Nri_PipelineDescSetColor(this.handle, format, writeMask);
    }

    // Conservative rasterization (1: every pixel a triangle touches at all; NriFeature.ConservativeRasterization)
    // or not (0, the default).
    // (Nri_PipelineDescSetConservativeRaster)
    setConservativeRaster(conservative: int) {
        Nri_PipelineDescSetConservativeRaster(this.handle, conservative);
    }

    // Vulkan's extra overestimation of conservative rasterization, in pixels (0 by default; at most
    // Nri_GetVulkanConservativeRasterizationProperties' maxExtraPrimitiveOverestimationSize); ignored on D3D.
    // (Nri_PipelineDescSetConservativeRasterExtraOverestimation)
    setConservativeRasterExtraOverestimation(size: float) {
        Nri_PipelineDescSetConservativeRasterExtraOverestimation(this.handle, size);
    }

    // (Nri_PipelineDescSetCullMode)
    setCullMode(cullMode: NriCullMode) {
        Nri_PipelineDescSetCullMode(this.handle, cullMode);
    }

    // The depth attachment's format, its test (NriCompareOp.None: off), whether it's written (1) and
    // whether the depth bounds test is on (1; NriFeature.DepthBoundsTest).
    // (Nri_PipelineDescSetDepth)
    setDepth(format: NriFormat, compareOp: NriCompareOp, write: int, boundsTest: int) {
        Nri_PipelineDescSetDepth(this.handle, format, compareOp, write, boundsTest);
    }

    // The depth bias of the triangles drawn: constant (D3D's integer DepthBias), clamped to clamp (0: not
    // clamped), plus slope times their depth slope, as NVRHI's setDepthBias (none by default).
    // (Nri_PipelineDescSetDepthBias)
    setDepthBias(constant: number, clamp: number, slope: number) {
        Nri_PipelineDescSetDepthBias(this.handle, constant, clamp, slope);
    }

    // Whether primitives are clipped at the near and far planes (1) or not (0: depth clamped, Donut's
    // default). Unset, NRI's default differs by API (clipped on Vulkan, not on D3D).
    // (Nri_PipelineDescSetDepthClip)
    setDepthClip(clip: int) {
        Nri_PipelineDescSetDepthClip(this.handle, clip);
    }

    // Counter-clockwise triangles are the front faces (1), or clockwise ones (0, the default).
    // (Nri_PipelineDescSetFrontCounterClockwise)
    setFrontCounterClockwise(counterClockwise: int) {
        Nri_PipelineDescSetFrontCounterClockwise(this.handle, counterClockwise);
    }

    // (Nri_PipelineDescSetInstanceStream)
    setInstanceStream(stream: int) {
        Nri_PipelineDescSetInstanceStream(this.handle, stream);
    }

    // How lines are drawn: their rasterization mode (NriLineRasterizationMode; Nri_GetLineRasterizationModes
    // tells which the device has), width (up to Nri_GetMaxLineWidth) and stipple (stipple 1: each bit of the
    // 16-bit pattern, from the lowest, a run of stippleFactor pixels drawn if set). D3D draws rectangular lines
    // as quadrilateral lines, Bresenham ones aliased, smooth ones alpha antialiased, and has no width or stipple.
    // (Nri_PipelineDescSetLineRasterization)
    setLineRasterization(mode: NriLineRasterizationMode, width: float, stipple: int, stippleFactor: int, stipplePattern: int) {
        Nri_PipelineDescSetLineRasterization(this.handle, mode, width, stipple, stippleFactor, stipplePattern);
    }

    // The color attachment's logic operation instead of blending (NriFeature.LogicOp; a UNORM or UINT
    // attachment, UINT on D3D12), in Vulkan's VkLogicOp order (0 CLEAR, 3 COPY, 5 NO_OP ... 15 SET).
    // NRI has no NO_OP: the attachment's color writes are turned off instead (the same result).
    // (Nri_PipelineDescSetLogicOp)
    setLogicOp(vkLogicOp: int) {
        Nri_PipelineDescSetLogicOp(this.handle, vkLogicOp);
    }

    // Patches of controlPointNum control points (NriTopology.PatchList: hull and domain shaders).
    // (Nri_PipelineDescSetPatchControlPoints)
    setPatchControlPoints(controlPointNum: int) {
        Nri_PipelineDescSetPatchControlPoints(this.handle, controlPointNum);
    }

    // The faces culled (None by default), clockwise ones the front.
    // The stream's attributes advance per instance, not per vertex.
    // Primitive restart for indexType's indices (0xFFFF or 0xFFFFFFFF end a strip).
    // (Nri_PipelineDescSetPrimitiveRestart)
    setPrimitiveRestart(indexType: NriIndexType) {
        Nri_PipelineDescSetPrimitiveRestart(this.handle, indexType);
    }

    // The color and depth attachments' samples (Nri_GetSupportedSampleCounts'; 1 by default): a pipeline
    // per sample count (NRI has no dynamic one).
    // (Nri_PipelineDescSetSampleCount)
    setSampleCount(sampleNum: int) {
        Nri_PipelineDescSetSampleCount(this.handle, sampleNum);
    }

    // Variable rate shading (NriFeature.VariableRateShading): the draws' shading rate is the one
    // Nri_CmdSetShadingRate sets, combined with the shading rate attachment's.
    // (Nri_PipelineDescSetShadingRate)
    setShadingRate(enabled: int) {
        Nri_PipelineDescSetShadingRate(this.handle, enabled);
    }

    // The primitives drawn (TriangleList by default).
    // (Nri_PipelineDescSetTopology)
    setTopology(topology: NriTopology) {
        Nri_PipelineDescSetTopology(this.handle, topology);
    }

    // Triangles drawn as their edges (1) or filled (0, the default).
    // (Nri_PipelineDescSetWireframe)
    setWireframe(wireframe: int) {
        Nri_PipelineDescSetWireframe(this.handle, wireframe);
    }
}

