// A NriPipelineLayoutDescHandle.
@final
export class NriPipelineLayoutDesc {
    constructor(public readonly handle: NriPipelineLayoutDescHandle) {
    }

    // A range of descriptorNum descriptors of type from register baseRegister (t, s or b by type) in set
    // setIndex (register space setIndex unless Nri_PipelineLayoutDescSetRegisterSpace says otherwise),
    // seen by stages (NriStage); flags: NriRangeFlags bits.
    // (Nri_PipelineLayoutDescAddRange)
    addRange(setIndex: int, baseRegister: int, descriptorNum: int, type: NriDescriptorType, stages: NriStage, flags: int) {
        Nri_PipelineLayoutDescAddRange(this.handle, setIndex, baseRegister, descriptorNum, type, stages, flags);
    }

    // size bytes of root constants (push constants) at register b<registerIndex>, in the root register
    // space, for stages.
    // (Nri_PipelineLayoutDescAddRootConstants)
    addRootConstants(registerIndex: int, size: int, stages: NriStage) {
        Nri_PipelineLayoutDescAddRootConstants(this.handle, registerIndex, size, stages);
    }

    // A root descriptor (push descriptor) of type (a constant buffer, or a structured buffer) at
    // register b, t or u<registerIndex> (by type), in the root register space, for stages: bound per draw
    // with an offset (Nri_CmdSetRootDescriptor), as a dynamic uniform buffer is, or per dispatch.
    // (Nri_PipelineLayoutDescAddRootDescriptor)
    addRootDescriptor(registerIndex: int, type: NriDescriptorType, stages: NriStage) {
        Nri_PipelineLayoutDescAddRootDescriptor(this.handle, registerIndex, type, stages);
    }

    // An immutable (static) sampler at register s<registerIndex>, in the root register space: filter for
    // minification and magnification, mipFilter for mips, addressMode on all axes, for stages.
    // (Nri_PipelineLayoutDescAddRootSampler)
    addRootSampler(registerIndex: int, filter: NriFilter, mipFilter: NriFilter, addressMode: NriAddressMode, stages: NriStage) {
        Nri_PipelineLayoutDescAddRootSampler(this.handle, registerIndex, filter, mipFilter, addressMode, stages);
    }

    // Pipeline layouts with descriptor sets, their ranges added one by one.
    // (Nri_CreatePipelineLayoutDesc)
    static create(): NriPipelineLayoutDesc {
        return new NriPipelineLayoutDesc(Nri_CreatePipelineLayoutDesc());
    }

    // (Nri_DestroyPipelineLayoutDesc)
    destroy() {
        Nri_DestroyPipelineLayoutDesc(this.handle);
    }

    // The register space of set setIndex (on Vulkan, its set number).
    // (Nri_PipelineLayoutDescSetRegisterSpace)
    setRegisterSpace(setIndex: int, registerSpace: int) {
        Nri_PipelineLayoutDescSetRegisterSpace(this.handle, setIndex, registerSpace);
    }

    // The register space of the root constants, descriptors and samplers (0 unless this says otherwise;
    // on Vulkan, the set of the root descriptors): one no descriptor set uses.
    // (Nri_PipelineLayoutDescSetRootRegisterSpace)
    setRootRegisterSpace(registerSpace: int) {
        Nri_PipelineLayoutDescSetRootRegisterSpace(this.handle, registerSpace);
    }
}

