// A NriQueueHandle.
@final
export class NriQueue {
    constructor(public readonly handle: NriQueueHandle) {
    }

    // Builds the TLAS from its instances on the queue, and waits (a scene that doesn't move); 0 on failure.
    // (Nri_BuildTopLevelASOnQueue)
    buildTopLevelAS(tlas: NriTopLevelAS): int {
        return Nri_BuildTopLevelASOnQueue(this.handle, tlas.handle);
    }

    // Its first build, on the queue (which this waits for); 0 on failure.
    // (Nri_BuildUpdatableBlasOnQueue)
    buildUpdatableBlas(blas: NriUpdatableBlas, vertexBuffer: NriBuffer, vertexOffset: int, indexBuffer: NriBuffer, indexOffset: int): int {
        return Nri_BuildUpdatableBlasOnQueue(this.handle, blas.handle, vertexBuffer.handle, vertexOffset, indexBuffer.handle, indexOffset);
    }

    // Async compute: a C++ worker thread (tslang code can't run on threads its GC doesn't know about)
    // that every intervalMicroseconds dispatches groupsX x groupsY groups of the compute pipeline on the
    // compute queue, each run writing the next free texture (bound by its descriptor set as set 0, the
    // run's index as root constants 0), and hands it to the render thread. The graphics queue signals
    // graphicsFence with the values Nri_ReleaseAsyncComputeTexture gives. Null on failure.
    // (Nri_CreateAsyncComputeLoop)
    createAsyncComputeLoop(device: NriDevice, graphicsFence: NriFence, pipelineLayout: NriPipelineLayout, pipeline: NriPipeline, descriptorPool: NriDescriptorPool, groupsX: int, groupsY: int, intervalMicroseconds: int): NriAsyncComputeLoop | null {
        const result = Nri_CreateAsyncComputeLoop(this.handle, device.handle, graphicsFence.handle, pipelineLayout.handle, pipeline.handle, descriptorPool.handle, groupsX, groupsY, intervalMicroseconds);
        return result ? new NriAsyncComputeLoop(result) : null;
    }

    // Commands
    // (Nri_CreateCommandAllocator)
    createCommandAllocator(): NriCommandAllocator {
        return new NriCommandAllocator(Nri_CreateCommandAllocator(this.handle));
    }

    // Signals the fence with value once the work submitted before is done.
    // (Nri_QueueSignal)
    signal(fence: NriFence, value: int) {
        Nri_QueueSignal(this.handle, fence.handle, value);
    }

    // Submission
    // Runs the command buffer once waitSemaphore (a swap chain's acquire) is signaled; signals
    // signalSemaphore (the swap chain's release) when done.
    // (Nri_QueueSubmit)
    submit(commandBuffer: NriCommandBuffer, waitSemaphore: NriFence, signalSemaphore: NriFence) {
        Nri_QueueSubmit(this.handle, commandBuffer.handle, waitSemaphore.handle, signalSemaphore.handle);
    }

    // Runs the command buffer after the work submitted before it, waiting for and signaling nothing.
    // (Nri_QueueSubmitCommandBuffer)
    submitCommandBuffer(commandBuffer: NriCommandBuffer) {
        Nri_QueueSubmitCommandBuffer(this.handle, commandBuffer.handle);
    }

    // Runs the command buffer once waitFence (if not null) reaches waitValue (e.g. another queue's
    // timeline), and signals signalFence with signalValue when done: one submission.
    // (Nri_QueueSubmitWithFences)
    submitWithFences(commandBuffer: NriCommandBuffer, waitFence: NriFence | null, waitValue: int, signalFence: NriFence, signalValue: int) {
        Nri_QueueSubmitWithFences(this.handle, commandBuffer.handle, waitFence ? waitFence.handle : null, waitValue, signalFence.handle, signalValue);
    }

    // Fills the texture's mip 0 with data (Ref of an int array element), rows (of blocks, for a
    // block-compressed format) rowPitch bytes apart, on the queue (which this waits for); leaves it in
    // NriTextureState.ShaderResource. 0 on failure.
    // (Nri_UploadTexture)
    uploadTexture(texture: NriTexture, data: Ref<int>, rowPitch: int): int {
        return Nri_UploadTexture(this.handle, texture.handle, data, rowPitch);
    }

    // Nri_UploadTexture from the file at offset; 0 if the texture's data would run past its end.
    // (Nri_UploadTextureFromFile)
    uploadTextureFromFile(texture: NriTexture, file: NriFile, offset: int, rowPitch: int): int {
        return Nri_UploadTextureFromFile(this.handle, texture.handle, file.handle, offset, rowPitch);
    }

    // Makes the work submitted to the queue from now on wait until the fence reaches value (on the GPU).
    // (Nri_QueueWait)
    wait(fence: NriFence, value: int) {
        Nri_QueueWait(this.handle, fence.handle, value);
    }
}

