// A NriSampleHandle.
@final
export class NriSample {
    constructor(public readonly handle: NriSampleHandle) {
    }

    // An option of the example's (a flag it reads with Nri_GetArg), which Nri_RunSample leaves out of
    // NRIFramework's command line (which would reject it); before Nri_RunSample.
    // (Nri_AddExampleOption)
    addExampleOption(option: string) {
        Nri_AddExampleOption(this.handle, option);
    }

    // As Nri_AddExampleOption, an option followed by valueNum values, left out too.
    // (Nri_AddExampleOptionWithValues)
    addExampleOptionWithValues(option: string, valueNum: int) {
        Nri_AddExampleOptionWithValues(this.handle, option, valueNum);
    }

    // (Nri_CmdCopyImguiData)
    copyImguiData(commandBuffer: NriCommandBuffer) {
        Nri_CmdCopyImguiData(this.handle, commandBuffer.handle);
    }

    // The application
    // (Nri_CreateSample)
    static create(): NriSample {
        return new NriSample(Nri_CreateSample());
    }

    // The device. Nri_CreateDevice fills the interface tables the other functions call through: one
    // device at a time.
    // The device of the adapter and with the validation the command line chose, null on failure.
    // (Nri_CreateDevice)
    createDevice(graphicsAPI: NriGraphicsAPI): NriDevice | null {
        const result = Nri_CreateDevice(this.handle, graphicsAPI);
        return result ? new NriDevice(result) : null;
    }

    // The swap chain: over the sample's window, its size, v-sync as the command line chose.
    // (Nri_CreateSwapChain)
    createSwapChain(device: NriDevice, queue: NriQueue, textureNum: int): NriSwapChainObject {
        return new NriSwapChainObject(Nri_CreateSwapChain(this.handle, device.handle, queue.handle, textureNum));
    }

    // As Nri_CreateSwapChain, with textures of format (NriSwapChainFormat).
    // (Nri_CreateSwapChainWithFormat)
    createSwapChainWithFormat(device: NriDevice, queue: NriQueue, textureNum: int, format: int): NriSwapChainObject {
        return new NriSwapChainObject(Nri_CreateSwapChainWithFormat(this.handle, device.handle, queue.handle, textureNum, format));
    }

    // Destroys the window; after the objects made on the device and the device are.
    // (Nri_DestroySample)
    destroy() {
        Nri_DestroySample(this.handle);
    }

    // (Nri_DestroyImgui)
    destroyImgui() {
        Nri_DestroyImgui(this.handle);
    }

    // Draws the UI into the render pass's color attachment, of attachmentFormat (sRGB or not).
    // (Nri_CmdDrawImgui)
    drawImgui(commandBuffer: NriCommandBuffer, attachmentFormat: NriFormat) {
        Nri_CmdDrawImgui(this.handle, commandBuffer.handle, attachmentFormat);
    }

    // Nri_CmdDrawImgui with the UI's colors as they are, not made linear for an attachment that isn't sRGB
    // (as Donut's ImGui renderer draws: into an HDR scene, for one).
    // (Nri_CmdDrawImguiUnconverted)
    drawImguiUnconverted(commandBuffer: NriCommandBuffer, attachmentFormat: NriFormat) {
        Nri_CmdDrawImguiUnconverted(this.handle, commandBuffer.handle, attachmentFormat);
    }

    // The last frame's duration, in seconds.
    // (Nri_GetFrameTime)
    getFrameTime(): number {
        return Nri_GetFrameTime(this.handle);
    }

    // How far the mouse moved since the last frame, in pixels (x right, y down).
    // (Nri_GetMouseDeltaX)
    getMouseDeltaX(): number {
        return Nri_GetMouseDeltaX(this.handle);
    }

    // (Nri_GetMouseDeltaY)
    getMouseDeltaY(): number {
        return Nri_GetMouseDeltaY(this.handle);
    }

    // The mouse wheel's turn this frame.
    // (Nri_GetMouseWheel)
    getMouseWheel(): number {
        return Nri_GetMouseWheel(this.handle);
    }

    // The cursor's position in the window, in pixels from its top left corner (x right, y down).
    // (Nri_GetMouseX)
    getMouseX(): number {
        return Nri_GetMouseX(this.handle);
    }

    // (Nri_GetMouseY)
    getMouseY(): number {
        return Nri_GetMouseY(this.handle);
    }

    // (Nri_GetOutputHeight)
    getOutputHeight(): int {
        return Nri_GetOutputHeight(this.handle);
    }

    // The output's size: the window's (its framebuffer's this frame, with Nri_UseResizableWindow).
    // (Nri_GetOutputWidth)
    getOutputWidth(): int {
        return Nri_GetOutputWidth(this.handle);
    }

    // The frames in flight (2 with v-sync).
    // (Nri_GetQueuedFrameNum)
    getQueuedFrameNum(): int {
        return Nri_GetQueuedFrameNum(this.handle);
    }

    // (Nri_ImguiEndFrame)
    imguiEndFrame() {
        Nri_ImguiEndFrame(this.handle);
    }

    // (Nri_ImguiNewFrame)
    imguiNewFrame() {
        Nri_ImguiNewFrame(this.handle);
    }

    // (Nri_ImguiRender)
    imguiRender() {
        Nri_ImguiRender(this.handle);
    }

    // ImGui and its renderer for the device (after Nri_UseImgui); 1, or 0 on failure. Destroyed with
    // Nri_DestroyImgui, before the device.
    // (Nri_InitImgui)
    initImgui(device: NriDevice): int {
        return Nri_InitImgui(this.handle, device.handle);
    }

    // 1 if the mouse button (0 left, 1 right, 2 middle) is down, else 0.
    // (Nri_IsButtonPressed)
    isButtonPressed(button: int): int {
        return Nri_IsButtonPressed(this.handle, button);
    }

    // 1 if the key (a GLFW key code: NriKey, or Donut's Key) is down, else 0.
    // (Nri_IsKeyPressed)
    isKeyPressed(key: int): int {
        return Nri_IsKeyPressed(this.handle, key);
    }

    // 1 if the key was pressed since the last call (for this key), else 0.
    // (Nri_IsKeyToggled)
    isKeyToggled(key: NriKey): int {
        return Nri_IsKeyToggled(this.handle, key);
    }

    // -test was given: Nri_RunSample rendered the test's frames.
    // (Nri_IsTest)
    isTest(): int {
        return Nri_IsTest(this.handle);
    }

    // 1 if the window has the input focus, else 0.
    // (Nri_IsWindowFocused)
    isWindowFocused(): int {
        return Nri_IsWindowFocused(this.handle);
    }

    // Parses the command line, makes the window (calling the initialize callback) and renders until
    // it's closed. Returns 0, or 1 if the command line or the initialization failed.
    // The command line is NRIFramework's (--api=D3D12, --debugAPI, --frameNum=<n>, --help, ...), with
    // the examples' options translated to it: -dx11, -dx12, -vk (--api), -debug (--debugAPI
    // --debugNRI), -test (renders testFrames frames, unfocused too, see Nri_IsTest), -testOutput <file>
    // (Nri_ReadBufferRGBA8 saves the frame it reads there, as PNG). V-sync is on.
    // (Nri_RunSample)
    run(argc: int, argv: Ref<string>, title: string, testFrames: int): int {
        return Nri_RunSample(this.handle, argc, argv, title, testFrames);
    }

    // 1: the cursor is hidden and captured (relative mouse movement); 0: normal.
    // (Nri_SetCursorDisabled)
    setCursorDisabled(disabled: int) {
        Nri_SetCursorDisabled(this.handle, disabled);
    }

    // Moves the cursor to (x, y), in pixels from the window's top left corner.
    // (Nri_SetCursorPosition)
    setCursorPosition(x: int, y: int) {
        Nri_SetCursorPosition(this.handle, x, y);
    }

    // Called by Nri_RunSample once the window is made: makes the device and what the frames need,
    // returns 0 on failure (then Nri_RunSample returns 1 without rendering).
    // (Nri_SetInitializeCallback)
    setInitializeCallback(handler: NriInitializeCallback) {
        Nri_SetInitializeCallback(this.handle, handler);
    }

    // Called at the start of each frame, before the input is read: waits for the frame's resources.
    // (Nri_SetLatencySleepCallback)
    setLatencySleepCallback(handler: NriFrameCallback) {
        Nri_SetLatencySleepCallback(this.handle, handler);
    }

    // (Nri_SetRenderFrameCallback)
    setRenderFrameCallback(handler: NriFrameCallback) {
        Nri_SetRenderFrameCallback(this.handle, handler);
    }

    // The window's size (1280 x 720 unless this is called, before Nri_RunSample).
    // (Nri_SetWindowSize)
    setWindowSize(width: int, height: int) {
        Nri_SetWindowSize(this.handle, width, height);
    }

    // (Nri_SetWindowTitle)
    setWindowTitle(title: string) {
        Nri_SetWindowTitle(this.handle, title);
    }

    // ImGui (NRIFramework's, drawn by NRI's Imgui extension). A frame: Nri_ImguiNewFrame, the widgets,
    // Nri_ImguiRender (before recording); Nri_CmdCopyImguiData outside a render pass, Nri_CmdDrawImgui
    // inside one; Nri_ImguiEndFrame after the frame's submission.
    // The example draws ImGui: before Nri_RunSample (on D3D11 the device then replays command buffers on
    // the immediate context, which ImGui's geometry needs).
    // (Nri_UseImgui)
    useImgui() {
        Nri_UseImgui(this.handle);
    }

    // The window can be resized (before Nri_RunSample; not under -test): Nri_GetOutputWidth/Height follow it
    // from frame to frame (no frames while it's minimized), and the example recreates its swap chain
    // (Nri_DeviceWaitIdle, Nri_DestroySwapChain, Nri_CreateSwapChain) and its targets of that size when the
    // size it made them at differs.
    // (Nri_UseResizableWindow)
    useResizableWindow() {
        Nri_UseResizableWindow(this.handle);
    }

    // Shaders' printf (Vulkan: the validation layer's, as Donut's AppOptions.ShaderPrintf), asked for before
    // Nri_RunSample: the Vulkan device gets the layer with its printf setting (without -debug too) and a
    // messenger for its messages.
    // (Nri_UseShaderPrintf)
    useShaderPrintf() {
        Nri_UseShaderPrintf(this.handle);
    }
}

// A NriShaderTableHandle.
@final
export class NriShaderTable {
    constructor(public readonly handle: NriShaderTableHandle) {
    }

    // (Nri_DestroyShaderTable)
    destroy() {
        Nri_DestroyShaderTable(this.handle);
    }
}

// A NriSwapChainHandle.
@final
export class NriSwapChainObject {
    constructor(public readonly handle: NriSwapChainHandle) {
    }

    // The index of the next texture to render into, once acquireSemaphore is signaled; -1 on failure.
    // (Nri_AcquireNextTexture)
    acquireNextTexture(acquireSemaphore: NriFence): int {
        return Nri_AcquireNextTexture(this.handle, acquireSemaphore.handle);
    }

    // (Nri_DestroySwapChain)
    destroy() {
        Nri_DestroySwapChain(this.handle);
    }

    // (Nri_GetSwapChainTexture)
    getTexture(index: int): NriTexture {
        return new NriTexture(Nri_GetSwapChainTexture(this.handle, index));
    }

    // The format (NriFormat) NRI gave the swap chain's textures.
    // (Nri_GetSwapChainTextureFormat)
    getTextureFormat(): int {
        return Nri_GetSwapChainTextureFormat(this.handle);
    }

    // (Nri_GetSwapChainTextureNum)
    getTextureNum(): int {
        return Nri_GetSwapChainTextureNum(this.handle);
    }

    // 1 if the display the swap chain's window is on is in HDR mode, else 0.
    // (Nri_IsDisplayHdr)
    isDisplayHdr(): int {
        return Nri_IsDisplayHdr(this.handle);
    }

    // Presents once releaseSemaphore is signaled; 0 on failure.
    // (Nri_QueuePresent)
    present(releaseSemaphore: NriFence): int {
        return Nri_QueuePresent(this.handle, releaseSemaphore.handle);
    }
}

// A NriTextureHandle.
@final
export class NriTexture {
    constructor(public readonly handle: NriTextureHandle) {
    }

    // A view of one layer of a texture array, as an array of that layer alone (Texture2DArray), for
    // shaders to read: what Donut binds to blit a slice.
    // (Nri_CreateTextureArrayLayerView)
    createArrayLayerView(format: NriFormat, layer: int): NriDescriptor {
        return new NriDescriptor(Nri_CreateTextureArrayLayerView(this.handle, format, layer));
    }

    // A view of all the layers and mips of a 2D texture array for shaders to read (Texture2DArray).
    // (Nri_CreateTextureArrayView)
    createArrayView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateTextureArrayView(this.handle, format));
    }

    // Attachment views of one layer of a texture array (a cubemap's face).
    // (Nri_CreateColorAttachmentLayerView)
    createColorAttachmentLayerView(format: NriFormat, layer: int): NriDescriptor {
        return new NriDescriptor(Nri_CreateColorAttachmentLayerView(this.handle, format, layer));
    }

    // A color attachment view of one mip level of the texture.
    // (Nri_CreateColorAttachmentMipView)
    createColorAttachmentMipView(format: NriFormat, mip: int): NriDescriptor {
        return new NriDescriptor(Nri_CreateColorAttachmentMipView(this.handle, format, mip));
    }

    // (Nri_CreateColorAttachmentView)
    createColorAttachmentView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateColorAttachmentView(this.handle, format));
    }

    // A view of a texture's layers (six per cube) and mips as an array of cubemaps (TextureCubeArray).
    // (Nri_CreateTextureCubeArrayView)
    createCubeArrayView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateTextureCubeArrayView(this.handle, format));
    }

    // A view of a cubemap's six faces and all its mips for shaders to read (TextureCube; Nri_LoadDdsTexture
    // loads cubemaps).
    // (Nri_CreateTextureCubeView)
    createCubeView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateTextureCubeView(this.handle, format));
    }

    // (Nri_CreateDepthAttachmentLayerView)
    createDepthAttachmentLayerView(format: NriFormat, layer: int): NriDescriptor {
        return new NriDescriptor(Nri_CreateDepthAttachmentLayerView(this.handle, format, layer));
    }

    // (Nri_CreateDepthAttachmentView)
    createDepthAttachmentView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateDepthAttachmentView(this.handle, format));
    }

    // A view of one mip level of a 2D texture for shaders to read.
    // (Nri_CreateTextureMipView)
    createMipView(format: NriFormat, mip: int): NriDescriptor {
        return new NriDescriptor(Nri_CreateTextureMipView(this.handle, format, mip));
    }

    // The view a shading rate attachment is rendered with (Nri_CmdBeginRenderingWithShadingRate).
    // (Nri_CreateShadingRateAttachmentView)
    createShadingRateAttachmentView(): NriDescriptor {
        return new NriDescriptor(Nri_CreateShadingRateAttachmentView(this.handle));
    }

    // A view of all the layers of a 2D texture array's mip 0 for compute shaders to write (RWTexture2DArray).
    // (Nri_CreateStorageTextureArrayView)
    createStorageArrayView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateStorageTextureArrayView(this.handle, format));
    }

    // A view of a 2D texture's mip 0 for compute shaders to write.
    // (Nri_CreateStorageTextureView)
    createStorageView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateStorageTextureView(this.handle, format));
    }

    // A view of a 2D texture's mips for shaders to read.
    // (Nri_CreateTextureView)
    createView(format: NriFormat): NriDescriptor {
        return new NriDescriptor(Nri_CreateTextureView(this.handle, format));
    }

    // Destroys a texture Nri_CreateDepthTexture made and frees its memory.
    // (Nri_DestroyTexture)
    destroy() {
        Nri_DestroyTexture(this.handle);
    }

    // Textures and views
    // (Nri_GetTextureFormat)
    getFormat(): NriFormat {
        return Nri_GetTextureFormat(this.handle);
    }

    // (Nri_GetTextureHeight)
    getHeight(): int {
        return Nri_GetTextureHeight(this.handle);
    }

    // (Nri_GetTextureMipNum)
    getMipNum(): int {
        return Nri_GetTextureMipNum(this.handle);
    }

    // The texture's size (its first level's) and mip levels.
    // (Nri_GetTextureWidth)
    getWidth(): int {
        return Nri_GetTextureWidth(this.handle);
    }
}

// A NriTextureLevelsHandle.
@final
export class NriTextureLevels {
    constructor(public readonly handle: NriTextureLevelsHandle) {
    }

    // A texture's levels gathered on the CPU: width x height, levelNum levels of format (set each with
    // Nri_SetTextureLevel), for Nri_CreateTextureFromLevels. Freed with Nri_DestroyTextureLevels.
    // (Nri_CreateTextureLevels)
    static create(width: int, height: int, levelNum: int, format: NriFormat): NriTextureLevels {
        return new NriTextureLevels(Nri_CreateTextureLevels(width, height, levelNum, format));
    }

    // (Nri_DestroyTextureLevels)
    destroy() {
        Nri_DestroyTextureLevels(this.handle);
    }

    // A level's data (copied; data some other library holds, e.g. TranscodedTexture.getLevelData's): its rows
    // (of blocks, for a block-compressed format) rowPitch bytes apart.
    // (Nri_SetTextureLevel)
    setTextureLevel(level: int, data: Opaque, rowPitch: int) {
        Nri_SetTextureLevel(this.handle, level, data, rowPitch);
    }
}

// A NriTopLevelASHandle.
@final
export class NriTopLevelAS {
    // The cached getters' results (made at the first call).
    private cachedTopLevelAccelerationStructure: NriAccelerationStructure | null = null;

    constructor(public readonly handle: NriTopLevelASHandle) {
    }

    // An instance of blas: transform, a row-major 3x4 matrix (12 floats from Ref of an f32 array element);
    // instanceId (InstanceID() in shaders); mask (ANDed with the rays'); hitGroupOffset, its first hit group
    // in the shader table; flags (nri::TopLevelInstanceBits: 0, none). Ignored past instanceMaxNum.
    // (Nri_TopLevelASAddInstance)
    addInstance(blas: NriAccelerationStructure, transform: Ref<f32>, instanceId: int, mask: int, hitGroupOffset: int, flags: int) {
        Nri_TopLevelASAddInstance(this.handle, blas.handle, transform, instanceId, mask, hitGroupOffset, flags);
    }

    // (Nri_TopLevelASClearInstances)
    clearInstances() {
        Nri_TopLevelASClearInstances(this.handle);
    }

    // (Nri_DestroyTopLevelAS)
    destroy() {
        Nri_DestroyTopLevelAS(this.handle);
    }

    // (Nri_GetTopLevelAccelerationStructure)
    @lends("this")
    getTopLevelAccelerationStructure(): NriAccelerationStructure {
        if (!this.cachedTopLevelAccelerationStructure) {
            this.cachedTopLevelAccelerationStructure = new NriAccelerationStructure(Nri_GetTopLevelAccelerationStructure(this.handle));
        }
        return this.cachedTopLevelAccelerationStructure;
    }
}

// An NriUpdatableBlasHandle.
@final
export class NriUpdatableBlas {
    // The cached getters' results (made at the first call).
    private cachedAccelerationStructure: NriAccelerationStructure | null = null;

    constructor(public readonly handle: NriUpdatableBlasHandle) {
    }

    // (Nri_DestroyUpdatableBlas)
    destroy() {
        Nri_DestroyUpdatableBlas(this.handle);
    }

    // The structure (for Nri_TopLevelASAddInstance).
    // (Nri_GetUpdatableBlasAccelerationStructure)
    @lends("this")
    getAccelerationStructure(): NriAccelerationStructure {
        if (!this.cachedAccelerationStructure) {
            this.cachedAccelerationStructure = new NriAccelerationStructure(Nri_GetUpdatableBlasAccelerationStructure(this.handle));
        }
        return this.cachedAccelerationStructure;
    }
}
